function getStoredAuth() {
  try {
    const token = window.localStorage.getItem(AUTH_TOKEN_KEY);
    const email = window.localStorage.getItem(AUTH_EMAIL_KEY);
    return token ? { token, email } : null;
  } catch (e) {
    return null;
  }
}

function storeAuth(token, email) {
  try {
    window.localStorage.setItem(AUTH_TOKEN_KEY, token);
    window.localStorage.setItem(AUTH_EMAIL_KEY, email || '');
  } catch (e) {
    // localStorage unavailable — session will just be tab-lived via React state
  }
}

function clearStoredAuth() {
  try {
    window.localStorage.removeItem(AUTH_TOKEN_KEY);
    window.localStorage.removeItem(AUTH_EMAIL_KEY);
  } catch (e) {}
}

function getDeviceId() {
  try {
    let id = window.localStorage.getItem(DEVICE_ID_KEY);
    if (!id) {
      id = (crypto.randomUUID ? crypto.randomUUID() : uid() + uid());
      window.localStorage.setItem(DEVICE_ID_KEY, id);
    }
    return id;
  } catch (e) {
    // localStorage unavailable — fall back to a session-only id
    return 'session-' + uid();
  }
}

// Remembers whether the Humidor Journal page was left in list or grid view, so the
// choice sticks across app opens instead of always starting back on list view.
function getStoredViewMode() {
  try {
    return window.localStorage.getItem(VIEW_MODE_KEY) === 'grid' ? 'grid' : 'list';
  } catch (e) {
    return 'list';
  }
}

function storeViewMode(mode) {
  try {
    window.localStorage.setItem(VIEW_MODE_KEY, mode);
  } catch (e) {
    // localStorage unavailable — the choice just won't stick this session
  }
}

